import re
from collections import OrderedDict

VAR_RE = re.compile(r'\{([A-Za-z0-9_-]+)\}')
METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
PERMS = {'ALLOW', 'DENY'}


def norm_path(p):
    return VAR_RE.sub('{var}', p)


def seg_count(p):
    return len([s for s in p.split('/') if s])


def main():
    with open('/app/input.txt') as f:
        content = f.read()

    # split into blocks of consecutive non-empty lines
    blocks = []
    cur = []
    for line in content.splitlines():
        if line.strip() == '':
            if cur:
                blocks.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        blocks.append(cur)

    ep_lines = blocks[0] if len(blocks) >= 1 else []
    be_lines = blocks[1] if len(blocks) >= 2 else []
    plan_lines = blocks[2] if len(blocks) >= 3 else []

    # ---- ENDPOINTS (hard cutoff) ----
    endpoints = []  # (orig_path, norm_path, method, role, perm)
    for line in ep_lines:
        f_ = line.split()
        if len(f_) != 4:
            break
        path, method, role, perm = f_
        method = method.upper()
        perm = perm.upper()
        if not path.strip() or not role.strip() or method not in METHODS or perm not in PERMS:
            break
        endpoints.append((path, norm_path(path), method, role, perm))

    # ---- BASE/EXCLUDE ----
    base = None
    exclude = set()
    for line in be_lines:
        f_ = line.split()
        if not f_:
            continue
        if f_[0] == 'base' and len(f_) >= 2:
            if base is None:
                base = f_[1]
        elif f_[0] == 'exclude':
            exclude.update(f_[1:])

    # ---- PLAN (hard cutoff) ----
    plan = []
    for line in plan_lines:
        f_ = line.split()
        if len(f_) != 2:
            break
        path, method = f_
        method = method.upper()
        if not path.strip() or method not in METHODS:
            break
        plan.append((path, norm_path(path), method))

    def base_ok(path):
        return base is None or path.startswith(base)

    # group endpoint indices by normalized path (input order)
    by_norm = OrderedDict()
    for i, ep in enumerate(endpoints):
        by_norm.setdefault(ep[1], []).append(i)

    # first original path per normalized path (input order)
    first_orig = {}
    for ep in endpoints:
        first_orig.setdefault(ep[1], ep[0])

    plan_norms = set((p, m) for _, p, m in plan)
    plan_paths = set(p for _, p, m in plan)

    # normalized paths that are strict prefixes of a plan endpoint's normalized path
    parents_needed = set()
    if plan:
        for pp in plan_paths:
            for cand in by_norm:
                if cand != pp and pp.startswith(cand):
                    parents_needed.add(cand)

    # ---- selection ----
    selected = set()
    if not plan:
        for i, ep in enumerate(endpoints):
            if base_ok(ep[0]) and ep[3] not in exclude:
                selected.add(i)
    else:
        for i, ep in enumerate(endpoints):
            path, npath, method, role, perm = ep
            if not base_ok(path):
                continue
            in_plan = (npath, method) in plan_norms
            is_parent = npath in parents_needed
            if not (in_plan or is_parent):
                continue
            if role not in exclude:
                selected.add(i)
            elif is_parent:
                # special inheritance case: only if ALL endpoints of this
                # parent path are for excluded roles
                if all(endpoints[j][3] in exclude for j in by_norm[npath]):
                    selected.add(i)

    # ---- dedup: first encountered (input order) per (norm_path, method, role) ----
    best = {}
    for i in sorted(selected):
        ep = endpoints[i]
        key = (ep[1], ep[2], ep[3])
        if key not in best:
            best[key] = ep

    out = []
    for (npath, method, role), ep in best.items():
        out.append((first_orig[npath], method, role, ep[4]))

    out.sort(key=lambda t: (-seg_count(t[0]), t[1], t[2], t[3]))

    with open('/app/output.txt', 'w') as f:
        if out:
            f.write('\n'.join('%s %s %s %s' % t for t in out) + '\n')
        else:
            f.write('\n')


if __name__ == '__main__':
    main()
